function renderEmployeeProfile() {
    root_element.innerHTML = styles + `<div class="env-wrapper" style="text-align: center; padding: 40px;">Loading Your Profile...</div>`;

    frappe.db.get_value('Employee', {'user_id': frappe.session.user}, 'name')
    .then(r => {
        if(r && r.message) {
            let employee_id = r.message.name;

            Promise.all([
                frappe.db.get_doc('Employee', employee_id),
                frappe.db.get_list('File', { filters: { attached_to_doctype: 'Employee', attached_to_name: employee_id }, fields: ['file_name', 'file_url'] })
            ]).then(([doc, files]) => {

                let envUserFiles = files || [];
                let img_html = doc.image ? `<img src="${doc.image}" class="env-profile-pic">` : `<div class="env-profile-pic" style="display:flex; align-items:center; justify-content:center; font-size:40px; color:#9ca3af;">👤</div>`;
                let formatDate = (dateString) => dateString ? frappe.datetime.str_to_user(dateString) : 'N/A';

                const envFolders = {
                    "Employee Contracts": ["contract", "agreement", "offer"],
                    "Medical & Health": ["doctor", "medical", "certificate", "health"],
                    "Leave Applications": ["leave", "annual", "holiday"],
                    "Compliance & Policies": ["police", "check", "conduct", "policy", "induction"],
                    "Other Documents": [] 
                };

                function getFilesInFolder(folderName) {
                    if (folderName === "Other Documents") {
                        return envUserFiles.filter(f => {
                            let name = f.file_name.toLowerCase();
                            let matchesOther = Object.entries(envFolders).some(([key, keywords]) => {
                                if(key === "Other Documents") return false;
                                return keywords.some(kw => name.includes(kw));
                            });
                            return !matchesOther;
                        });
                    }
                    let keywords = envFolders[folderName];
                    return envUserFiles.filter(f => { let name = f.file_name.toLowerCase(); return keywords.some(kw => name.includes(kw)); });
                }

                function triggerUpload(currentView, folderName = null) {
                    new frappe.ui.FileUploader({
                        doctype: 'Employee', docname: employee_id,
                        on_success: (file_doc) => {
                            frappe.db.get_list('File', { filters: { attached_to_doctype: 'Employee', attached_to_name: employee_id }, fields: ['file_name', 'file_url'] })
                            .then(updated_files => {
                                envUserFiles = updated_files || [];
                                if(currentView === 'files') { drawFiles(folderName); } else { drawFolders(); }
                                frappe.show_alert({message: 'File uploaded successfully!', indicator: 'green'});
                            });
                        }
                    });
                }

                // Core Layout HTML
                let html = styles + `
                    <div class="env-wrapper" style="padding: 0; background: transparent;">
                        <div class="env-banner">
                            <div style="display: flex; gap: 10px; align-items: flex-start;">
                                <button class="env-action-btn" id="btn-timesheet">📅 Timesheet</button>
                                <button class="env-action-btn" id="btn-leave">🏖️ Leave Application</button>
                            </div>
                        </div>

                        <div class="env-profile-container">
                            <div class="env-left-col">
                                ${img_html}
                                <h2 style="color: #0ea5e9; margin: 15px 0 20px 0;">${doc.employee_name}</h2>
                                <div class="env-detail-row"><div class="env-detail-label">Joined Date</div><div>${formatDate(doc.date_of_joining)}</div></div>
                                <div class="env-detail-row"><div class="env-detail-label">Position Title</div><div>${doc.custom_position_title || doc.designation || 'N/A'}</div></div>
                                <div class="env-detail-row"><div class="env-detail-label">Contact No</div><div>${doc.cell_number || 'N/A'}</div></div>
                                <div class="env-detail-row"><div class="env-detail-label">Email</div><div style="word-break: break-all;">${doc.company_email || 'N/A'}</div></div>
                                <div class="env-detail-row"><div class="env-detail-label">Employment Status</div><div>${doc.status}</div></div>
                                <div class="env-detail-row"><div class="env-detail-label">DOB</div><div>${formatDate(doc.date_of_birth)}</div></div>
                                <button class="env-action-btn primary" id="btn-update-info" style="margin-top: 20px; width: 100%; justify-content: center; padding: 10px;">Update Info</button>
                            </div>

                            <div class="env-right-col">
                                <div id="env-folder-header" style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px;"></div>
                                <div id="env-folder-grid" class="env-folder-grid"></div>
                            </div>
                        </div>
                    </div>
                `;

                root_element.innerHTML = html;

                // --- PROFILE BUTTON ROUTES ---
                // Routes directly to the custom enviro-weekly-timesheet page
                root_element.querySelector('#btn-timesheet').addEventListener('click', () => {
                    frappe.new_doc('Enviro Weekly Timesheet', {
                        employee: doc.name
                    });
                });                
                root_element.querySelector('#btn-leave').addEventListener('click', () => frappe.set_route('List', 'Leave Application'));
                root_element.querySelector('#btn-update-info').addEventListener('click', () => frappe.set_route('Form', 'Employee', doc.name));

                // --- FOLDERS LOGIC ---
                function drawFolders() {
                    let header = root_element.querySelector('#env-folder-header');
                    let grid = root_element.querySelector('#env-folder-grid');
                    header.innerHTML = `<h3 style="margin: 0; color: #374151;">Folders</h3><button class="env-action-btn primary" id="btn-upload-folder">+ Upload Document</button>`;
                    let gridHtml = '';
                    Object.keys(envFolders).forEach(folderName => {
                        let count = getFilesInFolder(folderName).length;
                        let emoji = folderName === "Other Documents" ? "📁" : "📂";
                        gridHtml += `<div class="env-folder" data-folder="${folderName}"><div style="font-size: 24px; color: #fbbf24;">${emoji}</div><div><div style="font-weight: bold;">${folderName}</div><div style="font-size: 11px; color: #9ca3af;">${count} files</div></div></div>`;
                    });
                    grid.innerHTML = gridHtml;
                    header.querySelector('#btn-upload-folder').addEventListener('click', () => triggerUpload('folders'));
                    grid.querySelectorAll('.env-folder').forEach(el => { el.addEventListener('click', function() { drawFiles(this.getAttribute('data-folder')); }); });
                }

                function drawFiles(folderName) {
                    let header = root_element.querySelector('#env-folder-header');
                    let grid = root_element.querySelector('#env-folder-grid');
                    header.innerHTML = `<div style="display: flex; align-items: center; gap: 10px;"><button class="env-action-btn" id="env-back-btn">🔙 Back</button><h3 style="margin: 0; color: #374151;">📂 ${folderName}</h3></div><button class="env-action-btn primary" id="btn-upload-file">+ Upload Document</button>`;
                    let files = getFilesInFolder(folderName);
                    let gridHtml = '';
                    if (files.length === 0) { gridHtml = `<div style="grid-column: 1 / -1; padding: 20px; color: #9ca3af; font-style: italic;">No documents in this folder yet.</div>`; } 
                    else { files.forEach(f => { gridHtml += `<div class="env-file" title="${f.file_name}" data-url="${f.file_url}">📄 ${f.file_name}</div>`; }); }
                    grid.innerHTML = gridHtml;
                    header.querySelector('#env-back-btn').addEventListener('click', drawFolders);
                    header.querySelector('#btn-upload-file').addEventListener('click', () => triggerUpload('files', folderName));
                    grid.querySelectorAll('.env-file').forEach(el => { el.addEventListener('click', function() { window.open(this.getAttribute('data-url'), '_blank'); }); });
                }

                drawFolders();
            });
        } else {
             root_element.innerHTML = styles + `<div class="env-wrapper" style="color: #dc2626; text-align: center; padding: 40px;"><b>Error:</b> No Employee profile is linked to your current user account.</div>`;
        }
    });
}

