                        <td>${format_currency(q.grand_total, q.currency)}</td>
                        <td><span class="status-badge ${badgeClass}">${statusText}</span></td>
                        <td>
                            <button class="action-btn view" data-name="${q.name}">View</button>
                            ${(q.docstatus === 1 && q.custom_accounts_approval_status === "Pending") ? 
                                `<button class="action-btn approve" data-name="${q.name}">Review / Approve</button>` : ''}
