                        <option value="06" ${state.selectedMonth === '06' ? 'selected' : ''}>Sales by month: Jun</option>
                        <option value="07" ${state.selectedMonth === '07' ? 'selected' : ''}>Sales by month: Jul</option>
                        <option value="08" ${state.selectedMonth === '08' ? 'selected' : ''}>Sales by month: Aug</option>
