            if(dateParts.length < 3) return false;

            let qYear = dateParts[0];
            let qMonth = dateParts[1];

            if (state.selectedYear && qYear !== state.selectedYear) return false;
            if (state.selectedMonth !== 'All' && qMonth !== state.selectedMonth) return false;

            return true;
        });

        let userStats = {};

        filteredPerfQuotes.forEach(q => {
            let displayName = (q.owner || 'Unknown').split('@')[0]; 
            if(displayName.length > 15) displayName = displayName.substring(0, 15);

            if (!userStats[displayName]) {
                userStats[displayName] = { made: 0, won: 0, pending: 0, lost: 0, initial: displayName.charAt(0).toUpperCase() };
            }

            userStats[displayName].made++;

            if (q.status === 'Ordered') {
                userStats[displayName].won++;
            } else if (q.status === 'Lost' || q.status === 'Cancelled' || q.status === 'Rejected') {
                userStats[displayName].lost++;
            } else {
                userStats[displayName].pending++;
            }
        });

        if (Object.keys(userStats).length === 0) {
            html += `<div style="padding: 20px; color: #888; font-style: italic;">No performance metrics found for this period.</div>`;
